import * as THREE from 'three';
import {pathPoint,pathHeading,terrainHeight,random,ROCKS,HABITAT,wrap} from './simulation.js?v=3';
import {animateModel} from './models.js';
import {vehicleModel,animalModel} from './assets.js';
const up=new THREE.Vector3(0,1,0);
const {halfWidth:hw,halfDepth:hd,roadHalfWidth:road}=HABITAT;
export function racerPose(r,alpha=1){const p=r.previous||r,pose={};for(const axis of ['x','y','z'])pose[axis]=p[axis]+(r[axis]-p[axis])*alpha;for(const angle of ['yaw','pitch','roll'])pose[angle]=r[angle]+wrap((p[angle]??r[angle])-r[angle])*(1-alpha);return pose;}
const mat=(color,other={})=>new THREE.MeshStandardMaterial({color,roughness:.83,...other});
function mesh(geometry,material,x=0,y=0,z=0){const m=new THREE.Mesh(geometry,material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;return m;}
function rod(a,b,r,material){const av=new THREE.Vector3(...a),bv=new THREE.Vector3(...b),d=bv.clone().sub(av);const m=mesh(new THREE.CylinderGeometry(r,r,d.length(),7),material);m.position.copy(av).add(bv).multiplyScalar(.5);m.quaternion.setFromUnitVectors(up,d.normalize());return m;}
export class RaceScene{
 constructor(canvas){this.renderer=new THREE.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'});this.renderer.setPixelRatio(Math.min(devicePixelRatio,1.6));this.renderer.shadowMap.enabled=true;this.renderer.shadowMap.type=THREE.PCFSoftShadowMap;this.renderer.outputColorSpace=THREE.SRGBColorSpace;this.renderer.toneMapping=THREE.ACESFilmicToneMapping;this.renderer.toneMappingExposure=1.18;this.scene=new THREE.Scene();this.camera=new THREE.PerspectiveCamera(48,1,.1,500);this.camera.position.set(69,45,77);this.target=new THREE.Vector3();this.effects=new Map();this.racers=[];this.animals=[];this.gates=[];this.plants=[];this.time=0;this.resize();window.addEventListener('resize',()=>this.resize());}
 resize(){this.renderer.setSize(innerWidth,innerHeight,false);this.camera.aspect=innerWidth/innerHeight;this.camera.updateProjectionMatrix();}
 clear(){this.scene.traverse(o=>{o.geometry?.dispose();if(o.material){for(const m of Array.isArray(o.material)?o.material:[o.material])m.dispose();}});this.scene.clear();this.effects.clear();this.racers=[];this.animals=[];this.gates=[];this.plants=[];}
 setWorld(sim){this.clear();this.mode=sim.mode;this.water=sim.config.water;const rng=random(this.water?160:318);this.scene.background=new THREE.Color(this.water?0x082c35:0x302a20);this.scene.fog=new THREE.FogExp2(this.water?0x12616a:0x7c7050,this.water?.0065:.005);
  this.scene.add(new THREE.HemisphereLight(this.water?0xc5fff0:0xfff2c7,this.water?0x354929:0x454327,2.2));const sun=new THREE.DirectionalLight(this.water?0xd6ffdc:0xffe6ad,3.8);sun.position.set(-24, sixty(),16);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-hw-10,right:hw+10,top:hd+10,bottom:-hd-10,near:1,far:220});sun.shadow.bias=-.0005;this.scene.add(sun);const fill=new THREE.DirectionalLight(0x47d8d1,.8);fill.position.set(32,13,-27);this.scene.add(fill);
  const terrain=new THREE.PlaneGeometry(hw*2,hd*2,100,72);terrain.rotateX(-Math.PI/2);const ps=terrain.attributes.position;for(let i=0;i<ps.count;i++)ps.setY(i,terrainHeight(ps.getX(i),ps.getZ(i)));terrain.computeVertexNormals();const ground=mesh(terrain,mat(this.water?0xa6b07b:0xbfa875));this.scene.add(ground);
  const plinth=mesh(new THREE.BoxGeometry(hw*2+2,4,hd*2+2),mat(this.water?0x173e37:0x383e26),0,-2,0);this.scene.add(plinth);
  const glass=mat(this.water?0x62d5d3:0xc7d4aa,{transparent:true,opacity:.05,roughness:.15,side:THREE.DoubleSide,depthWrite:false});for(const z of [-hd,hd])this.scene.add(mesh(new THREE.PlaneGeometry(hw*2,35),glass,0,16,z));for(const x of [-hw,hw]){const m=mesh(new THREE.PlaneGeometry(hd*2,35),glass,x,16,0);m.rotation.y=Math.PI/2;this.scene.add(m);}
  const edge=mat(this.water?0x77ae9e:0x999470,{metalness:.55,roughness:.4});for(const x of [-hw,hw])for(const z of [-hd,hd])this.scene.add(rod([x,-1,z],[x,34,z],.18,edge));for(const y of [-1,34]){for(const z of [-hd,hd])this.scene.add(rod([-hw,y,z],[hw,y,z],.18,edge));for(const x of [-hw,hw])this.scene.add(rod([x,y,-hd],[x,y,hd],.18,edge));}
  if(this.water){const surface=mesh(new THREE.PlaneGeometry(hw*2,hd*2),mat(0x71dbc9,{transparent:true,opacity:.055,side:THREE.DoubleSide,depthWrite:false}),0,31,0);surface.rotation.x=-Math.PI/2;this.scene.add(surface);}
  const rockGeo=new THREE.IcosahedronGeometry(1,1),rockMats=[mat(0x586c59),mat(0x798271),mat(0xa0a98c),mat(this.water?0x677e75:0x967f5c)];for(let i=0;i<105;i++){const x=(rng()-.5)*(hw*2-8),z=(rng()-.5)*(hd*2-8);const s=.35+rng()*2;const m=mesh(rockGeo,rockMats[i%4],x,terrainHeight(x,z)+s*.24,z);m.scale.set(s*1.5,s*.9,s);m.rotation.set(rng(),rng()*6,rng());this.scene.add(m);}
  // Deliberate giant set pieces establish the toy-scale aquarium/terrarium.
  for(const [x,z,s] of ROCKS){const m=mesh(rockGeo,rockMats[0],x,terrainHeight(x,z)+s*.6,z);m.scale.set(s,s*1.4,s*.8);this.scene.add(m);}
  for(let i=0;i<42;i++){const x=(rng()-.5)*(hw*2-8),z=(rng()-.5)*(hd*2-8);if(Math.hypot(x/HABITAT.trackX,z/HABITAT.trackZ)>.8&&Math.hypot(x/HABITAT.trackX,z/HABITAT.trackZ)<1.1&&!this.water)continue;this.addPlant(x,z,3+rng()*10,rng);}
  const drift=mat(0x60553b);for(const [a,b] of [[[0,3,-10],[15,9,0]],[[-14,3,7],[-3,11,2]],[[8,3,8],[19,6,15]]]){this.scene.add(rod(a,b,1.15,drift));this.scene.add(rod(b,[b[0]+4,b[1]+3,b[2]-3],.4,drift));}
  if(this.water){const pipe=mat(0x183f41);this.scene.add(rod([-36,1,-23],[-36,28,-23],1.5,pipe));this.scene.add(mesh(new THREE.BoxGeometry(9,7,5),mat(0x223f39),-33,5,-23));const holes=new THREE.MeshBasicMaterial({color:0x081e22});for(let i=0;i<6;i++)this.scene.add(mesh(new THREE.BoxGeometry(.4,4,.15),holes,-36+i*1.25,5,-20.45));}
  this.createRoute(sim);this.createParticles(rng);
  sim.racers.forEach(r=>{const g=vehicleModel(sim.mode,sim.config.colors[r.id]);this.racers.push(g);this.scene.add(g);});sim.animals.forEach(a=>{const g=animalModel(a.type);this.animals.push(g);this.scene.add(g);});this.camera.position.set(69,45,77);this.target.set(-10,7,0);this.camera.lookAt(this.target);this.cameraReady=false;
 }
 addPlant(x,z,height,rng){const g=new THREE.Group();g.position.set(x,terrainHeight(x,z),z);const shades=this.water?[0x467b49,0x649851,0x93b765,0x316e58]:[0x74994a,0x4e753e,0x9aaf56,0x3e6c46];const leaves=mat(shades[Math.floor(rng()*shades.length)],{side:THREE.DoubleSide});for(let j=0;j<5;j++){const angle=j*2.4+rng(),h=height*(.55+rng()*.45);const points=[new THREE.Vector3(0,0,0),new THREE.Vector3(Math.sin(angle)*.5,h*.4,Math.cos(angle)*.5),new THREE.Vector3(Math.sin(angle)*2.5,h*.8,Math.cos(angle)*2.5),new THREE.Vector3(Math.sin(angle)*3,h,Math.cos(angle)*3)];const tube=new THREE.TubeGeometry(new THREE.CatmullRomCurve3(points),7,this.water?.22:.15,4,false);g.add(mesh(tube,leaves));if(!this.water){for(let k=1;k<4;k++){const leaf=mesh(new THREE.SphereGeometry(1,6,4),leaves,points[2].x*k/3,h*k/4,points[2].z*k/3);leaf.scale.set(.8,.12,1.9);leaf.rotation.set(.3,angle+k,.35);g.add(leaf);}}}this.scene.add(g);this.plants.push({g,phase:rng()*6});}
 createRoute(sim){const points=Array.from({length:145},(_,i)=>{const p=pathPoint(sim.mode,i/144);return new THREE.Vector3(p.x,p.y,p.z)});if(this.water){const line=new THREE.Line(new THREE.BufferGeometry().setFromPoints(points),new THREE.LineDashedMaterial({color:0xb7ffd7,dashSize:.7,gapSize:1.1,transparent:true,opacity:.27}));line.computeLineDistances();this.scene.add(line);this.routeLine=line;}else{const vertices=[];for(let i=0;i<=180;i++){const t=i/180,p=pathPoint(sim.mode,t),h=pathHeading(sim.mode,t);for(const sign of [-1,1]){const x=p.x+Math.cos(h)*road*sign,z=p.z-Math.sin(h)*road*sign;vertices.push(x,terrainHeight(x,z)+.05,z);}}const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(vertices,3));const indices=[];for(let i=0;i<180;i++){const n=i*2;indices.push(n,n+1,n+2,n+1,n+3,n+2);}geo.setIndex(indices);geo.computeVertexNormals();this.scene.add(mesh(geo,mat(0xa68c5c,{side:THREE.DoubleSide})));for(let i=0;i<75;i++){const p=pathPoint(sim.mode,i/75),h=pathHeading(sim.mode,i/75);for(const s of [-1,1]){const x=p.x+Math.cos(h)*(road+.4)*s,z=p.z-Math.sin(h)*(road+.4)*s;const marker=mesh(new THREE.BoxGeometry(.25,.35,1.2),mat(i%2?0xcdbb8c:0x696344),x,terrainHeight(x,z)+.16,z);marker.rotation.y=h;this.scene.add(marker);}}}
  for(let i=0;i<sim.config.gates;i++){const g=new THREE.Group(),p=sim.gatePoint(i);g.position.set(p.x,p.y,p.z);g.rotation.y=pathHeading(sim.mode,i/sim.config.gates);const material=new THREE.MeshStandardMaterial({color:0x87d6ac,emissive:0x28543a,emissiveIntensity:.7,roughness:.35,metalness:.25,transparent:true,opacity:.8});if(this.water)g.add(mesh(new THREE.TorusGeometry(sim.config.radius,.18,8,48),material));else {g.add(rod([-road,-2,0],[-road,6,0],.2,material),rod([road,-2,0],[road,6,0],.2,material),rod([-road,6,0],[road,6,0],.24,material));}if(i===0){for(let j=0;j<10;j++){g.add(mesh(new THREE.BoxGeometry(1.2,.65,.15),mat(j%2?0xf6efd5:0x16392d),-5.4+j*1.2,this.water?sim.config.radius:6,0));}}g.userData.material=material;this.gates.push(g);this.scene.add(g);}
 }
 createParticles(rng){const coords=[];for(let i=0;i<260;i++)coords.push((rng()-.5)*(hw*2-6),2+rng()*29,(rng()-.5)*(hd*2-6));const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(coords,3));this.particles=new THREE.Points(g,new THREE.PointsMaterial({color:this.water?0xb0f9dd:0xffe6b9,size:this.water?.16:.07,transparent:true,opacity:.45,depthWrite:false}));this.scene.add(this.particles);}
 effect(key,create){if(!this.effects.has(key)){const g=create();this.effects.set(key,g);this.scene.add(g);}return this.effects.get(key);}
 update(sim,dt,menu=false,alpha=1){this.time=sim.time;const now=sim.time;
  this.gates.forEach((g,i)=>{const p=sim.gatePoint(i);g.position.set(p.x,p.y,p.z);const next=i===sim.racers[0].gate&&!menu;g.userData.material.color.setHex(next?0xd2ff67:this.water?0x68bda4:0xbda66d);g.userData.material.emissive.setHex(next?0x9bd63d:0x16372d);g.userData.material.emissiveIntensity=next?1.2:.3;g.userData.material.opacity=next?1:.6;g.scale.setScalar(next?1+Math.sin(now*3)*.025:1);});
  this.racers.forEach((g,i)=>{const r=sim.racers[i],p=racerPose(r,alpha);g.position.set(p.x,p.y,p.z);g.rotation.set(p.pitch,p.yaw,p.roll,'YXZ');g.visible=r.immune<=0||Math.floor(now*12)%3!==0;animateModel(g,now,r.speed,r.boosting);});
  this.animals.forEach((g,i)=>{const a=sim.animals[i];g.position.set(a.x,a.y,a.z);g.rotation.y=a.yaw;animateModel(g,now+a.phase,a.target?8:2,false);});
  for(const {g,phase} of this.plants){g.rotation.z=Math.sin(now*.6+phase)*.035;g.rotation.x=Math.cos(now*.4+phase)*.025;}
  const attr=this.particles.geometry.attributes.position;for(let i=0;i<attr.count;i++){attr.setY(i,(attr.getY(i)+dt*(this.water?.9:.14))%31);}attr.needsUpdate=true;
  const active=new Set();for(const f of sim.food){const key=`f${f.id}`;active.add(key);const g=this.effect(key,()=>{const a=new THREE.Group();for(let j=0;j<12;j++){const m=mesh(new THREE.IcosahedronGeometry(.22,0),mat(0xf4b757),Math.sin(j*8)*1.5,Math.cos(j*5)*.5,Math.cos(j*4)*1.5);a.add(m);}return a;});g.position.set(f.x,f.y,f.z);g.rotation.y=now*.4;g.scale.setScalar(Math.min(1,f.ttl));}
  for(const w of sim.waste){const key=`w${w.id}`;active.add(key);const g=this.effect(key,()=>{const g=new THREE.Group();for(let i=0;i<4;i++){const m=mesh(new THREE.SphereGeometry(.65,7,5),mat(0x695638,{transparent:true,opacity:this.water?.35:.9,depthWrite:!this.water}),Math.sin(i*2)*.4,i*.18,Math.cos(i*2)*.4);g.add(m);}return g;});g.position.set(w.x,w.y,w.z);g.scale.setScalar(w.radius);}
  for(const t of sim.tongues){const key=`t${t.id}`;active.add(key);const g=this.effect(key,()=>rod([0,0,0],[0,1,0],.18,mat(0xe99b93,{emissive:0x3d1515})));const a=new THREE.Vector3(t.from.x,t.from.y,t.from.z),b=new THREE.Vector3(t.to.x,t.to.y,t.to.z);const extend=Math.min(1,t.age/.25,t.ttl/.25);b.lerpVectors(a,b,extend);const d=b.clone().sub(a);g.position.copy(a).add(b).multiplyScalar(.5);g.scale.y=d.length();if(d.length()>.001)g.quaternion.setFromUnitVectors(up,d.normalize());}
  for(const [key,g] of this.effects)if(!active.has(key)){this.scene.remove(g);g.traverse(o=>{o.geometry?.dispose();o.material?.dispose();});this.effects.delete(key);}
  if(menu){const a=.72+Math.sin(now*.06)*.09;this.camera.position.set(Math.sin(a)*265,105,Math.cos(a)*265);this.target.set(innerWidth<800?-25:-30,8,2);this.camera.lookAt(this.target);this.camera.fov=48;this.camera.updateProjectionMatrix();this.scene.fog.density=this.water?.0025:.002;this.cameraReady=false;}
  else{const r=sim.racers[0],p=racerPose(r,alpha),f=new THREE.Vector3(Math.sin(p.yaw),0,Math.cos(p.yaw)),desired=new THREE.Vector3(p.x,p.y+(this.water?4.8:5.8),p.z).addScaledVector(f,-(this.water?15:18));desired.y=Math.max(terrainHeight(desired.x,desired.z)+3,desired.y);const look=new THREE.Vector3(p.x,p.y+.7,p.z).addScaledVector(f,12);const blend=this.cameraReady?1-Math.exp(-dt*6):1;this.camera.position.lerp(desired,blend);this.target.lerp(look,blend);this.camera.lookAt(this.target);this.cameraReady=true;this.camera.fov+=(r.boosting?70-this.camera.fov:64-this.camera.fov)*dt*3;this.camera.updateProjectionMatrix();this.scene.fog.density=this.water?.009:.0045;}
  this.renderer.render(this.scene,this.camera);
 }
}
function sixty(){return 60;}
